from pathlib import Path
p=Path(__file__).resolve().parents[1]/'app/src/main/assets/index.html'
s=p.read_text(encoding='utf-8')
if 'living-dex-journey-hub" content="5.2"' not in s:s=s.replace('</head>','<meta name="living-dex-journey-hub" content="5.2"/>\n</head>',1)
css=r'''
/* Journey Hub 5.2 — one professional destination for route, team and map. */
.jh52{position:fixed;inset:0;z-index:980;background:#f6f8fc;color:#17213c;display:flex;flex-direction:column}.jh52[hidden]{display:none!important}.jh52-head{padding:calc(12px + env(safe-area-inset-top)) 18px 12px;display:flex;align-items:center;gap:12px;background:rgba(246,248,252,.94);backdrop-filter:blur(16px);border-bottom:1px solid #e9edf4}.jh52-back{width:44px;height:44px;border:0;border-radius:15px;background:#fff;font-size:25px;color:#17213c;box-shadow:0 4px 15px rgba(35,48,79,.07)}.jh52-head h1{margin:0;font-size:25px;font-weight:950;letter-spacing:-.045em}.jh52-head small{display:block;color:#929caf;font-size:10px;margin-top:3px}.jh52-body{overflow:auto;flex:1;padding:16px 16px calc(30px + env(safe-area-inset-bottom))}.jh52-summary{padding:20px;border-radius:26px;background:linear-gradient(145deg,#18263e,#253a5c);color:#fff;box-shadow:0 15px 34px rgba(29,46,76,.16)}.jh52-eyebrow{font-size:10px;text-transform:uppercase;letter-spacing:.12em;font-weight:900;color:#ff8b8b}.jh52-summary h2{font-size:25px;margin:7px 0 6px;letter-spacing:-.04em}.jh52-summary p{margin:0;color:#cbd4e2;font-size:12px;line-height:1.45}.jh52-stat{display:flex;align-items:end;justify-content:space-between;margin-top:18px}.jh52-stat b{font-size:14px}.jh52-stat strong{font-size:28px}.jh52-bar{height:8px;background:rgba(255,255,255,.2);border-radius:99px;overflow:hidden;margin-top:9px}.jh52-bar i{height:100%;display:block;background:#ff5555;border-radius:99px}.jh52-tabs{position:sticky;top:-16px;z-index:5;margin:14px -2px 14px;padding:8px 2px;background:rgba(246,248,252,.94);backdrop-filter:blur(12px);display:grid;grid-template-columns:repeat(3,1fr);gap:7px}.jh52-tab{border:0;border-radius:14px;padding:11px 5px;background:#fff;color:#8d98aa;font-size:11px;font-weight:900;box-shadow:0 3px 12px rgba(35,48,79,.05)}.jh52-tab.active{background:#ff5555;color:#fff}.jh52-panel[hidden]{display:none!important}.jh52-card{background:#fff;border:1px solid #e9edf4;border-radius:24px;padding:18px;box-shadow:0 6px 20px rgba(35,48,79,.06)}.jh52-next{display:grid;grid-template-columns:54px 1fr auto;align-items:center;gap:12px}.jh52-icon{width:54px;height:54px;border-radius:18px;background:#fff0f0;color:#ff5555;display:grid;place-items:center;font-size:23px}.jh52-label{font-size:10px;letter-spacing:.12em;text-transform:uppercase;color:#9aa4b7;font-weight:900}.jh52-title{font-size:19px;font-weight:950;margin-top:5px}.jh52-sub{font-size:11px;color:#8e98aa;margin-top:5px}.jh52-steps{display:grid;gap:8px;margin-top:12px}.jh52-step{display:grid;grid-template-columns:38px 1fr auto;gap:10px;align-items:center;padding:12px;border-radius:17px;background:#fff;border:1px solid #edf0f5}.jh52-step.done{background:#f6fffb}.jh52-check{width:36px;height:36px;border-radius:50%;border:2px solid #dce1e9;background:#fff;font-weight:900}.jh52-step.done .jh52-check{background:#22c993;color:#fff;border-color:#22c993}.jh52-step b{font-size:12px}.jh52-step small{display:block;font-size:9px;color:#929caf;margin-top:2px}.jh52-lv{font-size:9px;font-weight:900;background:#f1f4f8;padding:6px 8px;border-radius:99px}.jh52-team{display:grid;grid-template-columns:repeat(2,1fr);gap:10px}.jh52-mon{border:1px solid #edf0f5;border-radius:20px;background:#fff;padding:12px;text-align:left;color:#17213c}.jh52-mon img{width:92px;height:92px;object-fit:contain;display:block;margin:auto}.jh52-mon b{display:block;font-size:13px}.jh52-mon small{font-size:9px;color:#929caf}.jh52-mapwrap{height:min(68vh,650px);border-radius:24px;overflow:hidden;background:#78b8ca;position:relative}.jh52-mapwrap .paldea-map{position:absolute!important;inset:0!important;width:100%!important;height:100%!important;min-height:0!important;border-radius:0!important}.jh52-mapwrap .paldea-map-art{object-fit:contain!important}.jh52-mapactions{display:flex;gap:8px;margin-top:10px}.jh52-mapactions button{flex:1;border:0;border-radius:14px;padding:12px;background:#fff;color:#17213c;font-size:11px;font-weight:850}.jh52-mapactions .primary{background:#ff5555;color:#fff}
'''
s=s.replace('</style>',css+'\n</style>',1)
js=r'''
// Journey Hub 5.2
function jh52Ensure(){if(document.getElementById('jh52'))return;document.body.insertAdjacentHTML('beforeend','<section id="jh52" class="jh52" hidden></section>')}
function jh52Data(){let g=GAMES.find(x=>x.id===state.activeGameId)||GAMES[0];let d={done:{},count:0,pct:0,next:1};try{d=ref42RouteStats()}catch(e){}return {g,d}}
function jh52Open(tab='route'){jh52Ensure();ref42HideAll?.();const el=document.getElementById('jh52');el.hidden=false;document.body.classList.add('ref42-page-open');jh52Render(tab)}
function jh52Close(){const el=document.getElementById('jh52');if(el)el.hidden=true;document.body.classList.remove('ref42-page-open');if(typeof go==='function')go('home');setTimeout(()=>{try{renderActiveGameHome()}catch(e){}},0)}
function jh52Header(tab,g){return `<div class="jh52-head"><button class="jh52-back" onclick="jh52Close()">‹</button><div><h1>Jornada</h1><small>${g.name} · acompanhamento da aventura</small></div></div>`}
function jh52Tabs(tab){return `<div class="jh52-tabs"><button class="jh52-tab ${tab==='route'?'active':''}" onclick="jh52Render('route')">Jornada</button><button class="jh52-tab ${tab==='team'?'active':''}" onclick="jh52Render('team')">Time recomendado</button><button class="jh52-tab ${tab==='map'?'active':''}" onclick="jh52Render('map')">Mapa</button></div>`}
function jh52Route(d){const route=window.SV_ROUTE||[];let next=route[Math.max(0,(d.next||1)-1)];return `<div class="jh52-card jh52-next"><span class="jh52-icon">⌁</span><div><div class="jh52-label">Próximo objetivo</div><div class="jh52-title">${next?next[0]:'Continue sua jornada'}</div><div class="jh52-sub">${next?'Siga a progressão recomendada · Lv.'+next[2]:'Acompanhe o progresso do jogo'}</div></div><span>›</span></div><div class="jh52-steps">${route.map((r,i)=>{let n=i+1,done=!!d.done[n];return `<article class="jh52-step ${done?'done':''}"><button class="jh52-check" onclick="ref42Toggle(${n});jh52Render('route')">${done?'✓':n}</button><div><b>${r[0]}</b><small>${r[1]==='gym'?'Ginásio':r[1]==='titan'?'Titã':'Team Star'} · ${r[3]}</small></div><span class="jh52-lv">Lv.${r[2]}</span></article>`}).join('')}</div>`}
function jh52Team(){let d=null;try{d=ref41Data()}catch(e){}let items=d?.next?.items||d?.ids?.map(id=>({id}))||[];return `<div class="jh52-card" style="margin-bottom:12px"><div class="jh52-label">Equipe para o próximo objetivo</div><div class="jh52-title">Recomendações da jornada</div><div class="jh52-sub">Pokémon sugeridos considerando o ponto atual da progressão.</div></div><div class="jh52-team">${items.map((x,i)=>`<button class="jh52-mon" onclick="openJourneyBuild(${x.id})">${pokemonImageHTML(x.id,'')}<b>${typeof svMemberName==='function'?svMemberName(x.id):'#'+x.id}</b><small>${i===0?'Melhor escolha':'Boa cobertura'}</small></button>`).join('')}</div>`}
function jh52Map(){return `<div class="jh52-mapwrap">${journeyMap()}</div><div class="jh52-mapactions"><button onclick="document.getElementById('ref50File')?.click()">Importar mapa</button><button class="primary" onclick="try{ref50Restore()}catch(e){}">Restaurar padrão</button></div>`}
function jh52Render(tab='route'){const el=document.getElementById('jh52'),{g,d}=jh52Data();if(!el)return;el.innerHTML=jh52Header(tab,g)+`<div class="jh52-body"><div class="jh52-summary"><div class="jh52-eyebrow">Jogo atual</div><h2>${g.name}</h2><p>Jornada, equipe recomendada e mapa reunidos em um único espaço.</p><div class="jh52-stat"><b>${d.count||0} objetivos concluídos</b><strong>${d.pct||0}%</strong></div><div class="jh52-bar"><i style="width:${d.pct||0}%"></i></div></div>${jh52Tabs(tab)}<div class="jh52-panel">${tab==='route'?jh52Route(d):tab==='team'?jh52Team():jh52Map()}</div></div>`}
// All journey entry points now lead to the unified hub.
window.ref42Open=function(kind='route'){jh52Open(kind)};
window.continueActiveGame=function(){jh52Open('route')};
const jh52Back=window.androidHandleBack;window.androidHandleBack=function(){const e=document.getElementById('jh52');if(e&&!e.hidden){jh52Close();return true}return typeof jh52Back==='function'?jh52Back():false};
jh52Ensure();
'''
s=s.replace('</body>','<script>'+js+'</script>\n</body>',1)
p.write_text(s,encoding='utf-8')
print('Journey Hub 5.2 applied')
